// The coding harnesses' marks, for the account picker: LobeHub's icons
// (@lobehub/icons-static-svg, MIT), rendered at 66 px (22 pt at 3x) and
// embedded, since a native module reaches no asset catalog. Grok's mark is
// one colour and draws in the text colour; the others keep their own.
import Foundation

#if os(iOS)
import UIKit

enum ProviderMarks {
    private static let png: [String: (data: String, template: Bool)] = [
        "claude": ("", false),
        "codex": ("", false),
        "gemini": ("", false),
        "antigravity": ("", false),
        "grok": ("", true),
    ]

    private static var cache: [String: UIImage] = [:]

    /// The provider's mark at 22 pt, or nil for one without.
    static func image(_ provider: String?) -> UIImage? {
        guard let provider, let entry = png[provider] else { return nil }
        if let cached = cache[provider] { return cached }
        guard let data = Data(base64Encoded: entry.data), let raw = UIImage(data: data, scale: 3) else { return nil }
        let image = entry.template ? raw.withRenderingMode(.alwaysTemplate) : raw.withRenderingMode(.alwaysOriginal)
        cache[provider] = image
        return image
    }
}
#endif
